fn solve(a: i8, b: i8, f: i8, k: i8) -> i8 {
    // Promote to a larger signed type to avoid accidental overflow
    let a = a as i32;
    let b = b as i32;
    let f = f as i32;
    let k = k as i32;

    // Single journey
    if k == 1 {
        // No refuel needed if capacity covers the whole distance
        if b >= a {
            return 0;
        }
        // Otherwise we must reach the station and then the far endpoint
        if b < f || b < (a - f) {
            return -1;
        }
        // Exactly one refuel at the station
        return 1;
    }

    // k >= 2
    // 1) Must be able to reach the station from whichever endpoint we start
    // 2) Must be able to go from station to the far endpoint
    // 3) Must be able to do a "round‐trip segment" from one endpoint back to the station
    //    (i.e. capacity >= 2*a - f)
    if b < f || b < (a - f) || b < (2 * a - f) {
        return -1;
    }

    // If the tank is so large that we never need to refuel at all over k journeys,
    // i.e. b ≥ k * a total distance, then answer is 0.
    if b >= k * a {
        return 0;
    }

    // Otherwise it is feasible, but we will need at least one refuel at the station
    1
}

#[cfg(test)]
mod tests {
    use super::solve;

    #[test]
    fn test_examples() {
        // Single journey, no refuel needed
        assert_eq!(solve(10, 10, 3, 1), 0);
        // Single journey, one refuel
        assert_eq!(solve(10, 7, 3, 1), 1);
        // Single journey, impossible
        assert_eq!(solve(10, 5, 3, 1), -1);

        // Double journey, need refuel
        assert_eq!(solve(10, 17, 3, 2), 1);
        // Double journey, can do both without refuel
        assert_eq!(solve(10, 20, 3, 2), 0);
        // Double journey, but too small tank: impossible
        assert_eq!(solve(10, 7, 3, 2), -1);

        // Three journeys, never refuel
        assert_eq!(solve(2, 10, 1, 5), 0);
        // Three journeys, but must refuel at least once
        assert_eq!(solve(10, 25, 3, 3), 1);
        // Three journeys, impossible
        assert_eq!(solve(10, 16, 3, 3), -1);
    }
}